local DEFAULT_ICON = "󰖯" -- md-window_maximize (U+F05AF)

-- case-insensitive index (built once at load)
local lower_map = {}
for name, glyph in pairs(map) do
	lower_map[name:lower()] = glyph
end

local icons = {}

--- Return the NF glyph for an application name (generic window if unknown).
function icons.get(app_name)
	if app_name == nil then
		return DEFAULT_ICON
	end
	return map[app_name] or lower_map[app_name:lower()] or DEFAULT_ICON
end

return icons
